package com.erp.management.controller;
import com.erp.management.entity.Purchase; import com.erp.management.repository.PurchaseRepository; import com.erp.management.service.TransactionService; import org.springframework.data.domain.Sort; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/purchases") public class PurchaseController {private final TransactionService service;private final PurchaseRepository purchases;public PurchaseController(TransactionService s,PurchaseRepository p){service=s;purchases=p;} @PostMapping("/create") ResponseEntity<?> create(@RequestBody Purchase p){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("success",true,"purchase",service.createPurchase(p)));}@GetMapping("/history") List<Purchase> history(){return purchases.findAll(Sort.by(Sort.Direction.DESC,"createdAt"));}}
